# -*- coding: utf-8 -*-
"""Stage and scene, from the shelter behind the performance."""
import json
from pathlib import Path
from lesson_authoring import entry as E
H=[['古希腊 skēnē','棚、帐篷；后来指戏剧中的舞台背景建筑']]
S=H+[['拉丁 scaena / scena → 法语 scène → 英语 scene','舞台、场景 → 一场戏；事情发生的现场']]
def D(h,a,b):return h+[[a,b]]
W=[
E('scene','/siːn/','场景；一场戏；现场；某种活动圈子','先想象舞台上那一块故事正在发生的地方；把舞台搬到现实中，事件发生的地点也成了 scene。','希腊 skēnē 经拉丁 scaena、法语 scène 传入；源头曾指棚或帐篷，后来与戏剧空间相连。',S,'a scene in a film 是电影中的一场戏；the scene of an accident 是事故现场；the music scene 是音乐活动圈。make a scene 指当众吵闹、闹得引人注目。','the opening scene；at the scene；the local music scene；make a scene。','scene 常是某个具体场景或活动环境；scenery 多是整体风景或舞台布景。',('The final scene takes place in a railway station.','最后一场戏发生在火车站。'),('Firefighters arrived at the scene within minutes.','消防员几分钟内就到了现场。'),('He did not want to make a scene in the restaurant.','他不想在餐馆里当众吵闹。'),sources=['https://www.etymonline.com/word/scene']),
E('scenery','/ˈsiːnəri/','风景；舞台布景','scene 是一处场景，scenery 常把眼前的山水或舞台上的背景整体看成一片。','英语 scene 的派生词，早期有 scenary，后来形式重整为 scenery；经历舞台布景到自然景色的用法。',D(S,'英语 scene → scenary / scenery','舞台场景 → 舞台布景；整体风景'),'通常是不可数名词：beautiful scenery，不说 a beautiful scenery。戏剧里还可指布置出环境的背景与景片。','mountain scenery；enjoy the scenery；stage scenery。','a scene 可以数一个场景；scenery 通常整体说风景，需要计数时可换 a view 或一段景色的具体说法。',('We stopped to enjoy the mountain scenery.','我们停下来欣赏山间风景。'),('The crew changed the scenery between acts.','工作人员在两幕之间更换了舞台布景。')),
E('scenic','/ˈsiːnɪk/','风景优美的；布景的；舞台景观相关的','一条路线的价值不只在快，而是沿途看起来漂亮，这种景色上的吸引力就是日常 scenic。','希腊 skēnikos 经拉丁 scaenicus、法语 scénique 传入；原与戏剧、舞台有关。',[H[0],['希腊 skēnikos → 拉丁 scaenicus → 法语 scénique','舞台的、戏剧的'],['英语 scenic','布景相关的；风景优美的']],'a scenic route 是风景路线，可能绕路；scenic design 在剧场里是舞台布景设计，不是旅游路线设计。','a scenic route；a scenic drive；scenic design。','scenery 是名词；scenic 是形容词。a scenic drive 指沿途有景可看的车程。',('We took the scenic route along the lake.','我们走了沿湖那条风景优美的路线。'),('She is responsible for the production’s scenic design.','她负责这部演出的舞台布景设计。')),
E('proscenium','英 /prəʊˈsiːniəm/；美 /proʊˈsiːniəm/','台口；舞台前部；镜框式舞台的框口','站在观众席看舞台，画面像被一个大框框住；pro- 的“在前面”帮助记住这个舞台前缘的词。','希腊 pro- 在前 + skēnē，形成 proskēnion，经拉丁 proscaenium 借入。',[H[0],['希腊 pro- + skēnē → proskēnion → 拉丁 proscaenium','舞台背景建筑之前的部分'],['英语 proscenium','舞台前部；台口及其框口']],'古代剧场与现代剧场所指部位并不完全相同。今天常见 proscenium arch，指把舞台与观众席分界、框住表演画面的台口。','a proscenium arch；a proscenium theatre。','stage 是整个舞台的常用说法；proscenium 特指前部或框口，不能泛指每一块演出地面。',('A painted border decorated the proscenium arch.','一道彩绘边饰装点着台口拱框。'),('The production was designed for a traditional proscenium theatre.','这部演出按传统镜框式剧场设计。'),sources=['https://www.merriam-webster.com/dictionary/proscenium']),
E('scenography','英 /siːˈnɒɡrəfi/；美 /siːˈnɑːɡrəfi/','舞台美术、布景设计；透视描绘','舞台并非只有演员，还要安排观众看到的空间、背景与视觉关系；scenography 关注怎样把这个世界造出来。','接拉丁 scenographia，远接希腊舞台与描绘的构词；现代可联系 scene 与 -graphy，但不是在英语里才从零组合。',[H[0],['希腊 skēnographia → 拉丁 scenographia','舞台背景、透视描绘'],['英语 scenography','舞台布景设计；透视表现']],'在剧场语境常说舞台视觉空间的设计。旧式艺术用法也可说透视表现，即把立体空间转到平面上，让远近关系看起来成立。','the scenography of a production；study scenography。','scenery 是做出来的布景；scenography 是如何设计、表现舞台空间的工作与艺术。',('The scenography used a single doorway to suggest an entire house.','舞台设计只用一个门口，就让观众联想到整栋房屋。'),('She studied scenography before designing sets for the theatre.','她先学习了舞台美术，后来为剧院设计布景。'),sources=['https://www.merriam-webster.com/dictionary/scenography','https://en.wiktionary.org/wiki/scenography#English']),
E('parascenium','/ˌpærəˈsiːniəm/','古希腊剧场舞台背景建筑两侧的突出翼部','把古代舞台背景建筑想成中间一面后墙、左右各伸出一翼；para- 标出它们在旁边。','新拉丁 parascenium，来自希腊 paraskēnion；para- 在旁 + skēnē。',[H[0],['希腊 para- + skēnē → paraskēnion','舞台背景建筑旁侧的部分'],['新拉丁 → 英语 parascenium','剧场两侧突出翼部；复数 parascenia']],'罕见的古剧场建筑术语。它说的是两侧结构，旧资料对房间具体用途有推测，不必把它固定等同于现代更衣室。','the parascenium of a theatre；paired parascenia。','proscenium 看前方；parascenium 看旁侧，两者的位置前缀不同。',('The plan shows a parascenium on either side of the stage building.','平面图显示舞台背景建筑两侧各有一个突出翼部。'),('Only the foundations of the parascenia remain.','两侧翼部如今只剩下地基。'),sources=['https://www.merriam-webster.com/dictionary/parascenium']),
E('scenario','英 /sɪˈnɑːriəʊ/；美 /sɪˈnerioʊ/','设想的情景；可能的发展局面；剧情梗概','先在脑中排一场戏：“如果这件事发生，接下来会怎样？”这串假设画面就是日常常说的 scenario。','意大利 scenario，接 scena“舞台”与 -ario，再上溯拉丁 scena；原来用于戏剧情节安排。',[H[0],['拉丁 scena / scenarius → 意大利 scenario','舞台场景 → 戏剧情节安排'],['英语 scenario','剧情梗概 → 假设情景、可能局面']],'规划时常比较 different scenarios；它描述一种可能性，不保证现实一定这样发展。也仍可在戏剧电影语境说梗概。','a possible scenario；under this scenario；consider several scenarios。','prediction 是预测会发生什么；scenario 是拿来推演的一种可能情景，可以同时准备多个。',('We planned for a scenario in which the main road was closed.','我们为主路封闭的情况作了预案。'),('In the most optimistic scenario, the work will finish by Friday.','在最乐观的情况下，工作会在周五前完成。'),sources=['https://www.etymonline.com/word/scenario']),
]
ROOT=dict(id='C1275',meaning='舞台、场景；事情正在发生的一片空间',core='SCEN = STAGE / SCENE',image='先搭一座表演用的棚，再给舞台配上背景。一个故事在里面发生，就是 scene；眼前整体的景物是 scenery；提前设想故事怎样展开，就是 scenario。',intro='希腊 skēnē 早期指棚、帐篷，后来指戏剧舞台背景建筑。经拉丁 scaena / scena，英语得到一批舞台、景色和情境词。它们让“事情发生的空间”从剧场走进日常语言。',forms='scenic 经希腊、拉丁和法语形容词路线；scenery 是英语派生；scenario 经意大利语。pro- 在前与 para- 在旁区分古剧场的位置，-graphy 接描绘。',branches=[['场景与整体景色','scene, scenery, scenic'],['情景推演','scenario'],['舞台空间与设计','proscenium, parascenium, scenography']],contrasts='scenery 通常不可数，scene 可以数一场或一幕。scenario 是一种设想，不是确定预测。proscenium 与 parascenium 不能仅因都属于剧场就混作同一个部位。',practice='The designer changed the scenery for the final scene. Meanwhile, the director considered a different scenario for the ending.\n\n设计师为最后一场戏更换了布景，导演则考虑了结尾的另一种情节安排。',words=[w['word'] for w in W])
if __name__=='__main__':
 t=Path(__file__).resolve().parents[1]/'.cache/batch200/drafts/root'
 for k,v in [('roots',[ROOT]),('words',W)]: (t/f'{k}_batch200_root_scen.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
